const records = $input.all();
const total = records.length;

if (total === 0) {
  return [{ json: {
    total: 0,
    catLines: '',
    priLines: '',
    duplicates: 0,
    approved: 0,
    rejected: 0,
    pending: 0,
    errors: 0
  }}];
}

const byCategory = {};
const byPriority = {};
let duplicates = 0, approved = 0, rejected = 0, pending = 0, errors = 0;

for (const r of records) {
  const f = r.json;
  const cat = f.category || 'Unknown';
  const pri = f.priority || 'Unknown';
  const status = f.status || '';
  const action = f.hs_action || '';
  byCategory[cat] = (byCategory[cat] || 0) + 1;
  byPriority[pri] = (byPriority[pri] || 0) + 1;
  if (action === 'updated') duplicates++;
  if (status === 'Approved') approved++;
  if (status === 'Rejected') rejected++;
  if (status === 'Processed') pending++;
  if (status === 'Error') errors++;
}

const catLines = Object.entries(byCategory)
  .sort((a, b) => b[1] - a[1])
  .map(([k, v]) => `  ${k}: ${v}`)
  .join('\n');

const priLines = Object.entries(byPriority)
  .sort((a, b) => b[1] - a[1])
  .map(([k, v]) => `  ${k}: ${v}`)
  .join('\n');

return [{ json: { total, catLines, priLines, duplicates, approved, rejected, pending, errors } }];
